//go:build !wasm

package actionbutton

import . "github.com/tinywasm/css"

func SSRInstance() *ActionButton { return &ActionButton{} }

func (b *ActionButton) RenderCSS() *Stylesheet {
	return New(
		Rule(clsBtnUrlUp,
			RuleContent(Decl{Prop: "margin-bottom", Val: "auto"}),
		),
		Rule(clsBtnUrlDown,
			RuleContent(Decl{Prop: "margin-top", Val: "auto"}),
			RuleContent(Decl{Prop: "margin-bottom", Val: ".3rem"}),
		),
		Rule(Selector("."+string(clsBtnUrlDown)+" ."+string(clsBtnUrl)),
			BackgroundColor(ColorBackground),
		),
		Rule(Selector("."+string(clsBtnUrlDown)+" svg."+string(clsBtnUrl)+" path"),
			RuleContent(Decl{Prop: "fill", Val: ColorPrimary.Var()}),
		),
		Rule("button",
			Cursor(Pointer),
			Border(None),
			Outline(None),
		),
		Rule(Selector("button[name*=\"btn\"]"),
			RuleContent(Decl{Prop: "background-position", Val: "center"}),
			RuleContent(Decl{Prop: "background-size", Val: "12%"}),
			RuleContent(Decl{Prop: "background-repeat", Val: "no-repeat"}),
			BackgroundColor(ColorPrimary),
			Color(ColorOnPrimary),
			Padding(Rem(0.4)),
			BorderRadius(Em(0.4)),
			Flex(Auto),
			Margin(Em(0.25)),
		),
		Rule(Selector("button[name*=\"btn\"]:disabled"),
			BackgroundColor(ColorMuted),
			PointerEvents(None),
		),
		Rule(Selector("button[name*=\"btn\"]:hover"),
			BackgroundColor(ColorSecondary),
		),
		Rule(Selector("button[name=\"btn_crudnew\"]"),
			BackgroundImage(Str("url(\"data:image/svg+xml;base64,\")")),
		),
		Rule(Selector("button[name=\"btn_cruddel\"]"),
			BackgroundImage(Str("url(\"data:image/svg+xml;base64,\")")),
		),
		Rule(clsContebuton,
			Display(Flex_),
			Height(Pct(100)),
			Background(ColorSurface),
			JustifyContent(Str("space-between")),
			RuleContent(Decl{Prop: "margin-left", Val: Space1.Var()}),
			Padding(Em(0.1)),
			BorderRadius(Em(0), Em(0), Em(0.4), Em(0.4)),
		),
		Rule(clsContCenteredBtn,
			RuleContent(Decl{Prop: "margin-top", Val: "0.5em"}),
			Display(Flex_),
			Height(Em(3)),
			Width(Pct(100)),
		),
		Rule(Selector("button[name=\"btn_crudcancel\"]"),
			BackgroundImage(Str("url(\"data:image/svg+xml;base64,\")")),
		),
		Rule(Selector("button[name=\"btn_crudsave\"]"),
			BackgroundImage(Str("url(\"data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIGNsYXNzPSdidG5fY3J1ZHNhdmUnIHZpZXdCb3g9JzAgMCAxNiAxNic+CjxwYXRoIGZpbGw9IiNmZmZmZmYiIGQ9Ik0xNCAwaC0xNHYxNmgxNnYtMTRsLTItMnpNOCAyaDJ2NGgtMnYtNHpNMTQgMTRoLTEydi0xMmgxdjVoOXYtNWgxLjE3MmwwLjgyOCAwLjgyOHYxMS4xNzJ6Ii8+Cjwvc3ZnPg==\")")),
		),
		Rule(Selector("button[name=\"btn-login\"]"),
			BackgroundImage(Str("url(\"data:image/svg+xml;base64,\")")),
		),
		Rule(Selector("button[name=\"btn_crudsend\"]"),
			BackgroundImage(Str("url(\"data:image/svg+xml;base64,\")")),
			RuleContent(Decl{Prop: "background-size", Val: "25%"}),
			Width(Pct(20)),
		),
		Rule(Selector("."+string(clsBtnUrl)+", ."+string(clsBtnSelected)+", ."+string(clsBtnUrlDisable)+", ."+string(clsBtnLogin)),
			BoxShadow(Str(".1em .1em .2em "+ColorSurface.Var())),
			Height(Rem(2.5)),
			BorderRadius(RadiusSm),
			Padding(Em(0.3)),
		),
		Rule(Selector("."+string(clsBtnUrl)+", ."+string(clsBtnUrlDisable)+", ."+string(clsBtnSelected)),
			RuleContent(Decl{Prop: "margin-top", Val: Space2.Var()}),
		),
		Rule(clsBtnUrlDisable,
			PointerEvents(None),
			Background(ColorMuted),
		),
		Rule(Selector("."+string(clsBtnUrl)+", ."+string(clsBtnLogin)),
			Background(ColorPrimary),
		),
		Rule(clsBtnSelected,
			Background(ColorSecondary),
		),
		Rule("input[type=submit]",
			BackgroundColor(ColorPrimary),
			Color(ColorOnPrimary),
			Cursor(Pointer),
			Border(None),
			Padding(Em(0.4), Em(0.8)),
			BorderRadius(Em(0.4)),
		),
		Rule(clsBtnUrlPulse,
			BoxShadow(Str(".1rem .1rem .2rem "+ColorSurface.Var())),
			Height(Rem(2.5)),
			BorderRadius(RadiusSm),
			Padding(Em(0.3)),
			Background(ColorMuted),
			RuleContent(Decl{Prop: "margin-top", Val: Space1.Var()}),
			Animation(Str("pulse-url 2s infinite")),
		),
		Keyframes("pulse-url",
			At("0%",
				Decl{Prop: "transform", Val: "scale(0.90)"},
				Decl{Prop: "box-shadow", Val: "0 0 0 0 color-mix(in srgb, " + ColorSecondary.Var() + ", transparent 30%)"},
			),
			At("70%",
				Decl{Prop: "transform", Val: "scale(1)"},
				Decl{Prop: "box-shadow", Val: "0 0 0 1vw transparent"},
			),
			At("100%",
				Background(ColorSecondary),
				Decl{Prop: "transform", Val: "scale(0.90)"},
				Decl{Prop: "box-shadow", Val: "0 0 0 0 transparent"},
			),
		),
		Rule(clsBtn,
			Padding(Rem(0.5), Rem(1)),
			Border(None),
			BorderRadius(Rem(0.25)),
			Cursor(Pointer),
			FontSize(Rem(1)),
		),
		Rule(clsBtnPrimary,
			Background(ColorPrimary),
			Color(ColorOnPrimary),
		),
		Rule(clsBtnSecondary,
			Background(ColorMuted),
			Color(ColorOnSurface),
		),
		Rule(clsBtnDanger,
			Background(ColorError),
			Color(ColorOnSurface),
		),
		Rule(clsBtn.Hover(),
			Opacity(0.9),
		),
	)
}

func (b *ActionButton) IconSvg() map[string]string {
	return nil
}
